SELECT product_id, product
FROM (
SELECT product_id, product, price
FROM products
WHERE price >= 20
) AS costly_products;

SELECT product_id, product
FROM (
SELECT product_id, product, price
FROM products
WHERE price >= 20
);

SELECT product_id,
(SELECT price FROM products) AS price
FROM products;

SELECT product_id, product, price
FROM products
WHERE price > (SELECT AVG(price) FROM products);

SELECT customer_id, first_name, country
FROM customers
WHERE country IN ('Germany', 'India');

